rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("可访问接口重复核查失败")
    assert responseBody.get("requestId")
    raise Blocked("公开 HTTP 没有查询评级窗口规则、重算评级或读取评级标签移除历史的接口，无法构造「不再满足条件」的前提，也无法核查风险标签移除过程及历史保留；评级提交与摘要查询只能观察已产生评级的结果，不能观察移除计算过程，查询接口调用成功不能代替目标场景通过，源用例结论为阻塞")
